CREATE TABLE pt_document_archives(id TEXT PRIMARY KEY, provider TEXT NOT NULL, archive_key TEXT NOT NULL, fingerprint TEXT NOT NULL, imported_at TEXT NOT NULL, imported_by TEXT NOT NULL, UNIQUE(provider,archive_key));
CREATE TABLE pt_archive_documents(id TEXT PRIMARY KEY, archive_id TEXT NOT NULL REFERENCES pt_document_archives(id), source_id TEXT NOT NULL, source_system TEXT NOT NULL, transaction_source_id TEXT NOT NULL, document_id TEXT NOT NULL REFERENCES pt_documents(id), sha256 TEXT NOT NULL, size INTEGER NOT NULL, placed_by TEXT, revision INTEGER NOT NULL DEFAULT 1, UNIQUE(archive_id,source_id));
CREATE TABLE pt_archive_source_links(source_system TEXT NOT NULL, source_kind TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, confirmed_by TEXT NOT NULL, confirmed_at TEXT NOT NULL, PRIMARY KEY(source_system,source_kind,source_id));
